"""Generate human-readable results from frozen artifacts; no tuning."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent

def report():
 result=json.loads((HERE/'results.json').read_text());coverage=json.loads((HERE/'coverage.json').read_text());verification=json.loads((HERE/'verification.json').read_text());s=result['summary'];rows=['# Neural game-context experiment','', 'Schedule context helped one specific neural task: full-feature residual carries MAE 1.277 → 1.228, about 3.9%, with lower error in all 12 assessment weeks. Target error improved about 1.1%; PPR did not improve. Combined context did not establish a broad neural advantage. No model or input family was promoted. This is retrospective revised-data development, not an untouched or prospective validation.','', '## Paired pooled prediction error','', 'Each cell is baseline → combined context MAE; lower is better. Same cohort, features apart from declared treatment, seed, chronological folds and two configuration choices per arm.','', '| Method | Targets | Carries | Source PPR |','|---|---:|---:|---:|']
 def item(target,method,family):return next(r for r in s if (r['target'],r['method'],r['family'])==(target,method,family))
 for method in result['methods']:
  vals=[f"{item(t,method,'baseline')['mae']:.3f} → {item(t,method,'combined')['mae']:.3f}" for t in result['targets']];rows.append('| '+method+' | '+' | '.join(vals)+' |')
 rows+=['','## Individual families','', '| Method / target | Baseline | Schedule | Venue | Teammate proxy | Opponent proxy | Combined |','|---|---:|---:|---:|---:|---:|---:|']
 for method in result['methods']:
  for target in result['targets']:rows.append('| '+method+' / '+target+' | '+' | '.join(f"{item(target,method,f)['mae']:.3f}" for f in result['families'])+' |')
 rows+=['','## Paired week uncertainty','', 'Combined minus baseline absolute error, with descriptive whole-week bootstrap 95% bounds. Negative means improvement. Twelve week blocks are few and dependent; intervals do not repair previous outcome inspection or select a confirmed winner. Schedule-only residual carries had paired difference −0.0493, descriptive95% bounds[−0.0657,−0.0335], improving12/12weeks.','', '| Method / target | Difference | 95% bounds | Improved weeks |','|---|---:|---:|---:|']
 for method in result['methods']:
  for target in result['targets']:
   r=item(target,method,'combined');a,b=r['week_cluster_bootstrap_95'];rows.append(f"| {method} / {target} | {r['paired_mae_delta']:+.3f} | [{a:+.3f}, {b:+.3f}] | {r['improved_weeks']}/{r['weeks']} |")
 rows+=['','## Inputs actually used','', '- 13 schedule inputs: home/neutral, cyclical weekday and ET/venue-local kickoff, >=19ET flag, own/opponent calendar rest and <=5day short rest. IANA timezones handle DST; neutral home is unknown; contradictory JAX00 international ID local time is unknown. Rest is derived from earlier regular-season game dates; first-week rest unknown.','- Four venue inputs: fixed covered, open air, retractable and unknown, inferred solely from earlier completed games at the stadium ID. Target roof/weather never enters the inputs. Retractable operational roof stays unknown. This measures structural venue context, not actual game roof position.','- Ten teammate plus ten opponent inputs: prior-three-game history count, previously observed target/carry workload absent or returning in the last completed game, QB historical participant counts, OL/defender prior snap workload absent in the last completed game, and canonical snap identity coverage. Teammate aggregates exclude the focal player. Names never join records; historical team/position and native bridge control identity.','', 'The paired baseline here is the full F3 68-input model. Earlier V4 F2 residual carries MAE 1.223 remains slightly better than this F3+schedule result 1.228; these context results do not demonstrate improvement over every earlier neural configuration. Trees still have lower pooled carry/PPR errors.\n\nThese are lagged participation proxies, not upcoming availability. Workload sums are observed lower bounds: unknown stat contributions are omitted, not inferred as healthy or absent. QB counts measure continuity rather than a forecast of who starts. OL/defender signals include only canonically resolved historical players; coverage remains visible. Missing group evidence remains NaN. Current registry statuses, target-game participant lists and target-game teammate/opponent scores never enter context.','', '## Actual availability: implemented contract, unsupported experiment','', 'availability.py exposes a scoring-only contract for original source receipts: game ID, source identifier/hash, publication and observed clocks before cutoff, effective canonical roster, report status, prior-game workload clock, and known opponent. Missing reports stay unknown. Out, doubtful and questionable remain distinct. Explicit prior out → current available can identify return counts; no realized DNP probability is fabricated. Synthetic contract fixtures verify this behavior; no historical availability model has been validated.','', '| Captured source | Rows | Update timestamp | Original predecision receipt | Primary training |','|---|---:|---|---|---|']
 for y,r in coverage['injury_inventory'].items():rows.append(f"| nflverse injuries{y} | {r['rows']} | {'yes' if r['has_date_modified'] else 'no'} | missing | excluded |")
 rows+=['', 'All 2023/24/25 injury records resolved to existing canonical native-ID mappings. That resolves identity, not chronology. Revised 2023/24 date_modified is an update clock, not a preserved original publication/capture receipt; 2025 has no update clock. No primary experiment used injury-status inputs. Inventory and immutably hashed downloads are retained separately.','', 'Official source documentation: [injury dictionary](https://nflreadr.nflverse.com/articles/dictionary_injuries.html) and [data update schedule](https://nflreadr.nflverse.com/articles/nflverse_data_schedule.html). The actual downloaded schema, not a stale search snippet, determines timestamp coverage.','', '## Feature coverage','', '| Input | Nonmissing rows | Coverage |','|---|---:|---:|']
 for name,r in coverage['features'].items():rows.append(f"| {name} | {r['nonmissing']}/{r['rows']} | {r['coverage']:.1%} |")
 rows+=['', 'Coverage is over all original matrix rows, not solely labeled Sunday assessment rows. coverage.json retains every game/team canonical snap bridge count. context_lineage.json retains prior games and cutoff for every matrix row; verification rejects target-game history references. Schedule/venue histories are reconstructed from revised releases captured after old decision times and may include revised schedule metadata; they do not establish original pregame evidence.','', '## Position results and subgroup limits','', '| Method / target / position | n | Baseline MAE | Combined MAE | Combined bias |','|---|---:|---:|---:|---:|']
 for method in result['methods']:
  for target in result['targets']:
   for pos,r in item(target,method,'combined')['position'].items():rows.append(f"| {method} / {target} / {pos} | {r['n']} | {item(target,method,'baseline')['position'][pos]['mae']:.3f} | {r['mae']:.3f} | {r['bias']:+.3f} |")
 rows+=['', 'Full fold metrics retain home/neutral/retractable/rest/missing-prior-workload subgroups, position/high workload errors, bias, empirical intervals and predefined PPR upside rankings. Subgroups with little or no coverage cannot support an effect claim. Assessment is Sunday Main, so weekday/prime-time have limited assessment variation; those features still vary in training. The model remains conditional on retrospectively observed positive snaps, excluding DNP rather than forecasting participation. Source PPR is not DraftKings scoring. Point errors/rankings do not validate portfolios, correlated lineup outcomes or profitability.','', '## Reproduction and verification','', f"324 fixed configuration fits completed in {result['runtime_seconds']:.1f}s; selected checkpoints saved for all 162 fold/target/arm/method fits. Residual/history anchoring and position hurdle/log-workload networks use V4 train-only preprocessing and whole-week stopping; trees receive identical treatment inputs. No new dependency or application change.", '', f"20 targeted context + reused V4 training tests passed. All {verification['checkpoints_reloaded']} saved checkpoints reloaded; {verification['prediction_rows']:,} row forecasts reproduce within floating point tolerance, and all {verification['clock_checked_context_rows']:,} contextual rows have prior-game cutoff lineage verified. Frozen spec/code/source/matrix/prediction/model hashes are retained. Checkpoint replay reconstructs full floating precision from original frozen sources; the ten-significant-digit CSV alone can move tree split ties. feature_matrix_full_precision.parquet and exact_input_receipt.json preserve those exact inputs separately, without altering original results.", '', '```sh','PYTHONPATH=. .venv/bin/python -m pytest research/neural_game_context_20261013/test_context.py research/neural_workload_benchmark_20261013/training_v4/test_training.py -q','.venv/bin/python research/neural_game_context_20261013/verify.py','.venv/bin/python research/neural_game_context_20261013/report.py','```','', 'run.py refuses an existing results.json; reproduce full training in a separately versioned copy after validating upstream source hashes. Do not overwrite the frozen study or reinterpret inspected historical weeks as untouched. Existing V4 prospective 2026 W6–9 protocol remains unchanged; no future outcomes or production projections/defaults were loaded/altered.']
 (HERE/'README.md').write_text('\n'.join(rows)+'\n')
if __name__=='__main__':report()
